-- -----------------------------------------------------
-- Window rules
-- -----------------------------------------------------

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    name = "opaque_browser",
    match = {
        class = "^(zen)$",
    },
    opaque = true,
})

hl.window_rule({
    name = "floating_volume_control",
    match = {
        title = "^(pavucontrol)$",
    },
    float = true,
})

hl.window_rule({
    name = "windowrule-6",
    match = {
        class = "^(Spotify)$",
    },
    workspace = "special:spotify silent",
})

hl.window_rule({
    name = "windowrule-7",
    match = {
        class = "^(ferdium)$",
    },
    workspace = "special:messanger silent",
})

hl.window_rule({
    name = "windowrule-8",
    match = {
        class = "^(discord)$",
    },
    workspace = "name:social silent",
})

hl.window_rule({
    name = "windowrule-9",
    match = {
        class = "^(steam)$",
    },
    workspace = "name:social silent",
})

hl.window_rule({
    name = "windowrule-10",
    match = {
        class = "^(steam_app_.*)$",
    },
    workspace = "name:Gaming silent",
})

hl.window_rule({
    name = "freecad-drag-and-drop",
    match = {
        class = "FreeCAD",
    },
    no_initial_focus = true,
})

-- Match Firefox PiP windows using the "Picture-in-Picture" title
hl.window_rule({
    name = "firefox_pip_standard",
    match = {
        class = "^(zen)$",
        title = "^(Picture-in-Picture)$",
    },
    float = true,
    pin = true,
    size = "840 472",
    move = "(monitor_w-900) (monitor_h-550)",
})

-- smart gaps
hl.workspace_rule({
    workspace = "w[tv1]s[false]",
    gaps_out = 0,
    gaps_in = 0,
})

hl.workspace_rule({
    workspace = "f[1]s[false]",
    gaps_out = 0,
    gaps_in = 0,
})

hl.window_rule({
    match = {
        float = 0,
        workspace = "w[tv1]s[false]",
    },
    border_size = 0,
    rounding = 0,
})

hl.window_rule({
    match = {
        float = 0,
        workspace = "f[1]s[false]",
    },
    border_size = 0,
    rounding = 0,
})

